"""External-only calibration of a normalized bigram, cache and latent-topic model."""
import hashlib,importlib.util,json,math,random,statistics,sys
from collections import Counter,deque
from vs import refcorpus

sp=importlib.util.spec_from_file_location('base','/tmp/voy_k038_taylor.py');base=importlib.util.module_from_spec(sp);sp.loader.exec_module(base)
BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')
N=30000;K=10;WINDOW=4096;TOPIC_ALPHA=1000.;DEV_DRAWS=4;TEST_DRAWS=64;NULL_DRAWS=32
# (topic weight, cache weight, mean topic-switch interval); fixed before fitting.
CANDIDATES=((0.,.3,8000),(.3,.3,2000),(.6,.3,2000),(.3,.3,8000),(.6,.3,8000),(.8,.1,8000))

class TopicModel:
 def __init__(self,train):
  self.core=base.Model(train); self.parts=[train[i*N//K:(i+1)*N//K] for i in range(K)]
  self.tc=[Counter(part) for part in self.parts]
 def probs(self,w,prev,queue,cache,topic_weight,cache_weight):
  b=self.core.base(w);row=self.core.succ.get(prev,{});ct=sum(row.values())
  big=(row.get(w,0)+base.ALPHA*b)/(ct+base.ALPHA)
  cached=(cache[w]+base.ALPHA*b)/(len(queue)+base.ALPHA)
  return [(1-cache_weight)*((1-topic_weight)*big+topic_weight*(c[w]+TOPIC_ALPHA*b)/(len(part)+TOPIC_ALPHA))+cache_weight*cached
          for c,part in zip(self.tc,self.parts)]
 def logloss(self,words,candidate):
  tw,cw,period=candidate;rho=1/period;weights=[1/K]*K;q=deque();cache=Counter();prev=None;loss=0.
  for w in words:
   probs=self.probs(w,prev,q,cache,tw,cw);p=sum(a*b for a,b in zip(weights,probs))
   if p<=0:raise ValueError('unmodelled token '+repr(w))
   loss-=math.log2(p);weights=[(1-rho)*(a*b/p)+rho/K for a,b in zip(weights,probs)]
   q.append(w);cache[w]+=1
   if len(q)>WINDOW:cache[q.popleft()]-=1
   prev=w
  return loss/len(words)
 def generate(self,n,candidate,seed):
  tw,cw,period=candidate;rng=random.Random(seed);state=rng.randrange(K);q=deque();out=[];prev=None
  for i in range(n):
   if i and rng.random()<1/period:state=rng.randrange(K)
   if rng.random()<cw:
    w=rng.choice(q) if q and rng.random()<len(q)/(len(q)+base.ALPHA) else self.core.drawbase(rng)
   elif rng.random()<tw:
    part=self.parts[state];w=rng.choice(part) if rng.random()<len(part)/(len(part)+TOPIC_ALPHA) else self.core.drawbase(rng)
   else:
    row=self.core.succ_lists.get(prev,[]);w=rng.choice(row) if row and rng.random()<len(row)/(len(row)+base.ALPHA) else self.core.drawbase(rng)
   out.append(w);q.append(w)
   if len(q)>WINDOW:q.popleft()
   prev=w
  return out

def metrics(words):
 return {str(w):{'exponent':(r:=base.compute_taylor(words,width=w)).exponent,'blocks':r.n_windows,'used':r.n_used_tokens} for w in base.WIDTHS}

def main():
 pins={x['id']:x for x in refcorpus.pins()};models={};data={}
 for b in BOOKS:
  with open(pins[b]['file'],'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256'],b
  ws=' '.join(refcorpus.blocks_of(b)).split();assert len(ws)>=3*N and all(0<len(w)<=base.LIMIT and set(w)<=set(base.LETTERS) for w in ws[:3*N])
  models[b]=TopicModel(ws[:N]);data[b]=(ws[N:2*N],ws[2*N:3*N])
 out={'config':{'books':BOOKS,'tokens_per_partition':N,'widths':base.WIDTHS,'topics':K,'topic_alpha':TOPIC_ALPHA,'cache_window':WINDOW,'candidates':CANDIDATES,'dev_draws':DEV_DRAWS,'test_draws':TEST_DRAWS,'null_draws':NULL_DRAWS},'development':{},'test':{}}
 # Fixed external-only objective: mean dev local loss minus fixed-cache loss,
 # plus ten times mean absolute five-width exponent error vs generator median.
 dev_real={b:metrics(data[b][0]) for b in BOOKS};dev_fixed={b:models[b].core.logloss(data[b][0],WINDOW,.3) for b in BOOKS}
 for ci,c in enumerate(CANDIDATES):
  rows=[]
  for bi,b in enumerate(BOOKS):
   model=models[b];sample=[metrics(model.generate(N,c,100000+bi*1000+ci*10+i)) for i in range(DEV_DRAWS)]
   errors=[abs(dev_real[b][str(w)]['exponent']-statistics.median(r[str(w)]['exponent'] for r in sample)) for w in base.WIDTHS]
   ll=model.logloss(data[b][0],c);rows.append({'book':b,'bits_per_token':ll,'fixed_cache_bits_per_token':dev_fixed[b],'mean_absolute_taylor_error':statistics.mean(errors)})
  obj=statistics.mean(r['bits_per_token']-r['fixed_cache_bits_per_token']+10*r['mean_absolute_taylor_error'] for r in rows)
  out['development'][str(ci)]={'candidate':c,'score':obj,'books':rows}
 selected=min(out['development'],key=lambda x:(out['development'][x]['score'],int(x)));c=CANDIDATES[int(selected)]
 out['selection']={'candidate_index':int(selected),'candidate':c,'rule':'min mean (dev loss − fixed-cache loss + 10 × mean absolute five-width dev exponent error); four simulated draws per book'}
 # Freeze the selected model, rules and external gate before inspecting any manuscript.
 for bi,b in enumerate(BOOKS):
  model=models[b];test=data[b][1];obs=metrics(test)
  generated=[metrics(model.generate(N,c,400000+bi*1000+i)) for i in range(TEST_DRAWS)]
  sh=[metrics(base.count_preserving_shuffle(test,seed=500000+bi*1000+i)) for i in range(NULL_DRAWS)]
  bg=[metrics(base.sample_empirical_bigram(test,n_tokens=N,seed=600000+bi*1000+i)) for i in range(NULL_DRAWS)]
  rows={}
  for width in base.WIDTHS:
   k=str(width);real=obs[k]['exponent'];vs=sorted(v[k]['exponent'] for v in generated);s=statistics.median(v[k]['exponent'] for v in sh);g=statistics.median(v[k]['exponent'] for v in bg)
   rows[k]={'observed':obs[k],'predictive_order4':vs[3],'predictive_order61':vs[60],
            'model_min':vs[0],'model_median':statistics.median(vs),'model_max':vs[-1],
            'shuffle_median':s,'bigram_median':g,'null_direction_gate':real>s and real>g,
            'predictive_interval_gate':vs[3]<=real<=vs[60]}
  ll=model.logloss(test,c);fixed=model.core.logloss(test,WINDOW,.3);zero=model.core.logloss(test,WINDOW,0.)
  local=ll<=fixed and ll<=zero
  out['test'][b]={'widths':rows,'selected_bits_per_token':ll,'fixed_cache_bits_per_token':fixed,'no_cache_bits_per_token':zero,'local_gate':local,
                  'joint_gate':local and all(x['null_direction_gate'] and x['predictive_interval_gate'] for x in rows.values())}
  print('finished',b,file=sys.stderr,flush=True)
 out['all_works_gate']=all(v['joint_gate'] for v in out['test'].values())
 print(json.dumps(out,indent=2))

if __name__=='__main__':main()

