"""External-first calibration of a normalized bigram/cache model, without Voynich data."""
import hashlib,importlib.util,json,math,random,statistics
from collections import Counter,defaultdict,deque
from functools import lru_cache
from vs import refcorpus
METRIC='/tmp/taylor_metric.py'
with open(METRIC,'rb') as f: assert hashlib.sha256(f.read()).hexdigest()=='554276d115500f2960831ab45910d9fc1c9625e1d06ac79ccb37b0ca16d58545'
spec=importlib.util.spec_from_file_location('taylor_metric',METRIC)
metric=importlib.util.module_from_spec(spec)
# dataclass resolves its class module at import time
import sys
sys.modules[spec.name]=metric
spec.loader.exec_module(metric)
compute_taylor=metric.compute_taylor
count_preserving_shuffle=metric.count_preserving_shuffle
sample_empirical_bigram=metric.sample_empirical_bigram

BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')
N=30000; WIDTHS=(2810,4215,5620,7025,8430); DRAWS=16
CACHE_WEIGHTS=(0,.1,.3,.5); WINDOWS=(256,1024,4096)
ALPHA=4.;CHAR_MIX=.1; CHAR_SMOOTH=.2; LIMIT=30
LETTERS='abcdefghijklmnopqrstuvwxyz'; CHARSET=LETTERS+'$'

class Model:
 def __init__(self,train):
  self.words=list(train);self.wc=Counter(train);self.succ=defaultdict(Counter);self.succ_lists=defaultdict(list);self.cc=defaultdict(Counter)
  for a,b in zip(train,train[1:]):self.succ[a][b]+=1;self.succ_lists[a].append(b)
  for w in train:
   for a,b in zip('$'+w,w+'$'):self.cc[a][b]+=1
  self.chars={}
  for a in CHARSET:
   opts=LETTERS if a=='$' else CHARSET
   weights=[self.cc[a][b]+CHAR_SMOOTH for b in opts];total=sum(weights)
   self.chars[a]=(opts,weights,{b:w/total for b,w in zip(opts,weights)})
 @lru_cache(maxsize=100000)
 def cp(self,w):
  if not w or len(w)>LIMIT or any(c not in LETTERS for c in w):return 0.
  prob=1.;prev='$'
  for c in w:prob*=self.chars[prev][2][c];prev=c
  return prob*(self.chars[prev][2]['$'] if len(w)<LIMIT else 1.)
 @lru_cache(maxsize=100000)
 def base(self,w):return (1-CHAR_MIX)*self.wc[w]/len(self.words)+CHAR_MIX*self.cp(w)
 def logloss(self,words,W,weight):
  queue=deque();cache=Counter();loss=0.;prev=None
  for w in words:
   base=self.base(w); row=self.succ.get(prev,{}); n=sum(row.values())
   big=(row.get(w,0)+ALPHA*base)/(n+ALPHA)
   cn=len(queue);cached=(cache[w]+ALPHA*base)/(cn+ALPHA)
   prob=(1-weight)*big+weight*cached
   if prob<=0:raise ValueError('unmodelled token '+repr(w))
   loss-=math.log2(prob);queue.append(w);cache[w]+=1
   if len(queue)>W:
    old=queue.popleft();cache[old]-=1
   prev=w
  return loss/len(words)
 def drawbase(self,rng):
  if rng.random()>=CHAR_MIX:return rng.choice(self.words)
  out=[];prev='$'
  while len(out)<LIMIT:
   opts,weights,_=self.chars[prev]; c=rng.choices(opts,weights=weights,k=1)[0]
   if c=='$':break
   out.append(c);prev=c
  return ''.join(out)
 def generate(self,n,W,weight,seed):
  rng=random.Random(seed);q=deque();out=[];prev=None
  for i in range(n):
   if rng.random()<weight:
    w=rng.choice(q) if q and rng.random()<len(q)/(len(q)+ALPHA) else self.drawbase(rng)
   else:
    row=self.succ_lists.get(prev,[])
    w=rng.choice(row) if row and rng.random()<len(row)/(len(row)+ALPHA) else self.drawbase(rng)
   out.append(w);q.append(w)
   if len(q)>W:q.popleft()
   prev=w
  return out

def estimates(tokens):
 return {str(w):{'exponent':(r:=compute_taylor(tokens,width=w)).exponent,'blocks':r.n_windows,'used':r.n_used_tokens,'types':r.n_fitted_types} for w in WIDTHS}

def main():
 pins={e['id']:e for e in refcorpus.pins()};out={'config':{'books':BOOKS,'segment_tokens':N,'widths':WIDTHS,'draws':DRAWS,'weights':CACHE_WEIGHTS,'windows':WINDOWS,'alpha':ALPHA,'char_mix':CHAR_MIX,'char_smooth':CHAR_SMOOTH,'char_limit':LIMIT},'dev':{},'test':{}}
 models={};sets={}
 for b in BOOKS:
  with open(pins[b]['file'],'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256'],b
  words=' '.join(refcorpus.blocks_of(b)).split();assert len(words)>=3*N and all(0<len(w)<=LIMIT and set(w)<=set(LETTERS) for w in words[:3*N])
  train,dev,test=words[:N],words[N:2*N],words[2*N:3*N];models[b]=Model(train);sets[b]=(dev,test)
 for W in WINDOWS:
  for weight in CACHE_WEIGHTS:
   key=f'{W}:{weight}';losses=[models[b].logloss(sets[b][0],W,weight) for b in BOOKS];out['dev'][key]=losses
 selected=min(out['dev'],key=lambda k:(statistics.mean(out['dev'][k]),k));W,w=selected.split(':');W=int(W);weight=float(w);out['selected']={'window':W,'weight':weight,'rule':'minimum mean dev bits/token across four books; ties lexicographic'}
 # Freeze all rules and parameters above, before any manuscript comparison. No manuscript is read here.
 for bi,b in enumerate(BOOKS):
  model=models[b];test=sets[b][1];actual=estimates(test);modelsamples=[];shuffles=[];bigrams=[]
  for i in range(DRAWS):
   modelsamples.append(estimates(model.generate(N,W,weight,10000+bi*100+i)))
   shuffles.append(estimates(count_preserving_shuffle(test,seed=20000+bi*100+i)))
   bigrams.append(estimates(sample_empirical_bigram(test,n_tokens=N,seed=30000+bi*100+i)))
  rows={}
  for width in WIDTHS:
   k=str(width);obs=actual[k]['exponent'];gen=[x[k]['exponent'] for x in modelsamples];sh=[x[k]['exponent'] for x in shuffles];bg=[x[k]['exponent'] for x in bigrams]
   rows[k]={'observed':actual[k],'model_min':min(gen),'model_max':max(gen),'model_median':statistics.median(gen),'shuffle_median':statistics.median(sh),'bigram_median':statistics.median(bg),'external_direction_gate':obs>statistics.median(sh) and obs>statistics.median(bg),'in_model_range':min(gen)<=obs<=max(gen)}
  ll=model.logloss(test,W,weight);baseline=model.logloss(test,W,0)
  out['test'][b]={'widths':rows,'selected_bits_per_token':ll,'bigram_bits_per_token':baseline,'local_gate':ll<=baseline,'joint_gate':ll<=baseline and all(r['external_direction_gate'] and r['in_model_range'] for r in rows.values())}
 out['all_works_gate']=all(r['joint_gate'] for r in out['test'].values())
 print(json.dumps(out,indent=2))

if __name__=='__main__':main()
